dtype = torch.float16, varlen = True, dropout_p = 0.5
@pytest.mark.flash_attention_backward @pytest.mark.skipif( flag_gems.vendor_name != "nvidia", reason="direct generic NVIDIA core regression" ) @pytest.mark.parametrize("dtype", [torch.float16, torch.bfloat16]) @pytest.mark.parametrize( "varlen", [pytest.param(False, id="dense"), pytest.param(True, id="varlen")] ) @pytest.mark.parametrize("dropout_p", [0.0, 0.5]) def test_dropout_derivative_nonzero_qkv(dtype, varlen, dropout_p): torch.manual_seed(197) m, n, heads, width, seed = 128, 256, 2, 32, 7331 q = 0.5 * torch.randn((1, m, heads, width), dtype=dtype, device=flag_gems.device) k = 0.5 * torch.randn((1, n, heads, width), dtype=dtype, device=flag_gems.device) v = 0.5 * torch.randn_like(k) # An unscaled cotangent directly constrains the nonzero dK computation. grad = 0.5 * torch.randn_like(q) keep = torch.ones((1, heads, m, n), dtype=torch.bool, device=flag_gems.device) if dropout_p: _backward_mask[(triton.cdiv(keep.numel(), 256),)]( keep, seed, m, n, heads, varlen, 256 ) q_ref, k_ref, v_ref = [x.double().requires_grad_() for x in (q, k, v)] scores = ( q_ref.transpose(1, 2) @ k_ref.transpose(1, 2).transpose(-1, -2) ) * width**-0.5 probability = scores.softmax(-1) dropped = probability * keep.double() / (1 - dropout_p) reference = (dropped @ v_ref.transpose(1, 2)).transpose(1, 2) expected = torch.autograd.grad(reference, (q_ref, k_ref, v_ref), grad.double()) out = reference.detach().to(dtype).contiguous() lse = scores.detach().logsumexp(-1).float() options = dict( max_seqlen_q=m, max_seqlen_k=n, is_dropout=bool(dropout_p), dropout_p=dropout_p, rng_state=(seed, 0), softmax_scale=width**-0.5, ) args = (grad, q, k, v, out, lse) if varlen: args = tuple(t.squeeze(0) for t in args[:5]) + (lse.squeeze(0).T.contiguous(),) options.update( cu_seq_q=torch.tensor([0, m], dtype=torch.int32, device=flag_gems.device), cu_seq_k=torch.tensor([0, n], dtype=torch.int32, device=flag_gems.device), ) actual = flash_attn_backward(*args, **options)[:3] for name, result, target in zip(("dQ", "dK"), actual[:2], expected[:2]): if varlen: result = result.unsqueeze(0) > torch.testing.assert_close( result.double(), target, rtol=0.016 if dtype == torch.bfloat16 else 0.001, atol=1e-4, msg=lambda message: name + ": " + message, ) E AssertionError: dK: Tensor-likes are not close! E E Mismatched elements: 16205 / 16384 (98.9%) E Greatest absolute difference: 0.04423422728306064 at index (0, 71, 0, 11) (up to 0.0001 allowed) E Greatest relative difference: 3078.5437172966826 at index (0, 192, 1, 13) (up to 0.001 allowed)
